import subprocess
import os
import shutil
from glob import glob
def task_func(src_folder, dst_folder):
    if not os.path.isdir(src_folder) or not os.path.isdir(dst_folder):
        raise OSError("Invalid source or destination folder")

    if not os.path.exists(dst_folder):
        os.makedirs(dst_folder)

    src_files = glob(os.path.join(src_folder, '*'))
    failed_files = []

    for file in src_files:
        try:
            subprocess.run(['gzip', file], check=True)
            compressed_file = file + '.gz'
            shutil.move(compressed_file, dst_folder)
        except subprocess.CalledProcessError:
            failed_files.append(os.path.basename(file))

    success = len(failed_files) == 0
    message = "All files compressed and moved successfully" if success else "Some files failed to compress or move"

    return {
        'success': success,
        'message': message,
        'failed_files': failed_files
    }

